SELECT 'supplier_invoice_lines.item_id->items' AS fk, count(*) AS violations FROM "supplier_invoice_lines" c WHERE c."item_id" IS NOT NULL AND ((SELECT h.org_id FROM "supplier_invoices" h WHERE h.id = c."supplier_invoice_id") IS NULL OR (SELECT t.org_id FROM "items" t WHERE t.id = c."item_id") IS NULL OR (SELECT h.org_id FROM "supplier_invoices" h WHERE h.id = c."supplier_invoice_id") <> (SELECT t.org_id FROM "items" t WHERE t.id = c."item_id"))
UNION ALL
SELECT 'supplier_return_lines.delivery_line_id->delivery_lines' AS fk, count(*) AS violations FROM "supplier_return_lines" c WHERE c."delivery_line_id" IS NOT NULL AND ((SELECT h.org_id FROM "supplier_returns" h WHERE h.id = c."return_id") IS NULL OR (SELECT p.org_id FROM "delivery_lines" x JOIN "deliveries" p ON p.id = x."delivery_id" WHERE x.id = c."delivery_line_id") IS NULL OR (SELECT h.org_id FROM "supplier_returns" h WHERE h.id = c."return_id") <> (SELECT p.org_id FROM "delivery_lines" x JOIN "deliveries" p ON p.id = x."delivery_id" WHERE x.id = c."delivery_line_id"))
UNION ALL
SELECT 'supplier_return_lines.item_id->items' AS fk, count(*) AS violations FROM "supplier_return_lines" c WHERE c."item_id" IS NOT NULL AND ((SELECT h.org_id FROM "supplier_returns" h WHERE h.id = c."return_id") IS NULL OR (SELECT t.org_id FROM "items" t WHERE t.id = c."item_id") IS NULL OR (SELECT h.org_id FROM "supplier_returns" h WHERE h.id = c."return_id") <> (SELECT t.org_id FROM "items" t WHERE t.id = c."item_id"))
UNION ALL
SELECT 'supplier_return_lines.location_id->stock_locations' AS fk, count(*) AS violations FROM "supplier_return_lines" c WHERE c."location_id" IS NOT NULL AND ((SELECT h.org_id FROM "supplier_returns" h WHERE h.id = c."return_id") IS NULL OR (SELECT t.org_id FROM "stock_locations" t WHERE t.id = c."location_id") IS NULL OR (SELECT h.org_id FROM "supplier_returns" h WHERE h.id = c."return_id") <> (SELECT t.org_id FROM "stock_locations" t WHERE t.id = c."location_id"))
UNION ALL
SELECT 'supplier_return_lines.movement_id->stock_movements' AS fk, count(*) AS violations FROM "supplier_return_lines" c WHERE c."movement_id" IS NOT NULL AND ((SELECT h.org_id FROM "supplier_returns" h WHERE h.id = c."return_id") IS NULL OR (SELECT t.org_id FROM "stock_movements" t WHERE t.id = c."movement_id") IS NULL OR (SELECT h.org_id FROM "supplier_returns" h WHERE h.id = c."return_id") <> (SELECT t.org_id FROM "stock_movements" t WHERE t.id = c."movement_id"))
UNION ALL
SELECT 'till_count_lines.counted_by->persons' AS fk, count(*) AS violations FROM "till_count_lines" c WHERE c."counted_by" IS NOT NULL AND ((SELECT h.org_id FROM "till_custody_shifts" h WHERE h.id = c."shift_id") IS NULL OR (SELECT t.org_id FROM "persons" t WHERE t.id = c."counted_by") IS NULL OR (SELECT h.org_id FROM "till_custody_shifts" h WHERE h.id = c."shift_id") <> (SELECT t.org_id FROM "persons" t WHERE t.id = c."counted_by"))
UNION ALL
SELECT 'till_count_lines.money_account_id->money_accounts' AS fk, count(*) AS violations FROM "till_count_lines" c WHERE c."money_account_id" IS NOT NULL AND ((SELECT h.org_id FROM "till_custody_shifts" h WHERE h.id = c."shift_id") IS NULL OR (SELECT t.org_id FROM "money_accounts" t WHERE t.id = c."money_account_id") IS NULL OR (SELECT h.org_id FROM "till_custody_shifts" h WHERE h.id = c."shift_id") <> (SELECT t.org_id FROM "money_accounts" t WHERE t.id = c."money_account_id"))
ORDER BY 1;
